import {test} from 'node:test';
import assert from 'node:assert/strict';
import {canMove, move} from '../src/status.mjs';

test('hidden check', async () => {
  assert.equal(canMove('shipped', 'returned'), true);
  assert.equal(canMove('shipped', 'delivered'), true);
  assert.equal(canMove('returned', 'delivered'), false);
  assert.equal(canMove('paid', 'returned'), false);
  assert.equal(move({status: 'shipped'}, 'returned').status, 'returned');
});
